start = await yuki_workspace_read({"path": "/workspace/start.txt"})
path = start["data"]["text"].strip()
visited = []
seen = set()
while path and path != "END" and path not in seen and len(visited) < 2000:
    seen.add(path)
    r = await yuki_workspace_read({"path": "/workspace/" + path})
    txt = r["data"]["text"]
    d = {}
    for line in txt.splitlines():
        if "=" in line:
            k, v = line.split("=", 1)
            d[k.strip()] = v.strip()
    if "value" not in d:
        break
    val = int(d["value"])
    visited.append((path, val))
    nxt = d.get("left") if val % 2 == 0 else d.get("right")
    path = nxt
{"n": len(visited), "tail": path, "total": sum(v for _, v in visited), "visited": visited}

